  index 0000000..613b23d
  --- /dev/null
  +++ b/web/src/components/MultiSelectDropdown.tsx
  @@ -0,0 +1,122 @@
  +import { useEffect, useRef } from "react";
  +import { Check, ChevronDown } from "lucide-react";
  +import { css } from "../../styled-system/css";
  +
  +export interface MultiSelectOption<T extends string> {
  +	value: T;
  +	label: string;
  +}
  +
  +export interface MultiSelectDropdownProps<T extends string> {
  +	label: string;
  +	allLabel: string;
  +	options: readonly MultiSelectOption<T>[];
  +	selected: readonly T[];
  +	onChange: (selected: T[]) => void;
  +}
  +
  +export function MultiSelectDropdown<T extends string>({
  +	label,
  +	allLabel,
  +	options,
  +	selected,
  +	onChange,
  +}: MultiSelectDropdownProps<T>) {
  +	const detailsRef = useRef<HTMLDetailsElement>(null);
  +	const selectedSet = new Set(selected);
  +	const summary = selected.length === 0
  +		? allLabel
  +		: selected.length === 1
  +			? options.find((option) => option.value === selected[0])?.label ?? selected[0]
  +			: `${selected.length} selected`;
  +
  +	useEffect(() => {
  +		const closeOnOutsideClick = (event: MouseEvent) => {
  +			const details = detailsRef.current;
  +			if (details?.open && !details.contains(event.target as Node)) details.open = false;
  +		};
  +		const closeOnEscape = (event: KeyboardEvent) => {
  +			if (event.key !== "Escape" || !detailsRef.current?.open) return;
  +			detailsRef.current.open = false;
  +			detailsRef.current.querySelector("summary")?.focus();
  +		};
  +		document.addEventListener("mousedown", closeOnOutsideClick);
  +		document.addEventListener("keydown", closeOnEscape);
  +		return () => {
  +			document.removeEventListener("mousedown", closeOnOutsideClick);
  +			document.removeEventListener("keydown", closeOnEscape);
  +		};
  +	}, []);
  +
  +	const toggle = (value: T) => {
  +		onChange(selectedSet.has(value)
  +			? selected.filter((entry) => entry !== value)
  +			: [...selected, value]);
  +	};
  +
  +	return (
  +		<details ref={detailsRef} className={css({ position: "relative", minWidth: 0 })}>
  +			<summary
  +				aria-label={label}
  +				className={css({
  +					display: "flex",
  +					minHeight: "2.25rem",
  +					cursor: "pointer",
  +					listStyle: "none",
  +					alignItems: "center",
  +					justifyContent: "space-between",
  +					gap: "0.5rem",
  +					overflow: "hidden",
  +					borderRadius: "0.375rem",
  +					border: "2px solid var(--border)",
  +					background: "var(--background)",
  +					paddingInline: "0.625rem",
  +					fontSize: { base: "0.75rem", sm: "0.875rem" },
  +					"&::-webkit-details-marker": { display: "none" },
  +					_focusVisible: { outline: "2px solid var(--primary)", outlineOffset: "2px" },
  +				})}
  +			>
  +				<span className={css({ minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" })}>{summary}</span>
  +				<ChevronDown size={14} aria-hidden="true" className={css({ flexShrink: 0, transition: "transform 150ms", "details[open] &": { transform: "rotate(180deg)" } })} />
  +			</summary>
  +			<div
  +				className={css({
  +					position: "absolute",
  +					top: "calc(100% + 0.25rem)",
  +					right: 0,
  +					zIndex: 30,
  +					width: "max-content",
  +					minWidth: "100%",
  +					maxWidth: "min(20rem, calc(100vw - 2rem))",
  +					maxHeight: "16rem",
  +					overflowY: "auto",
  +					borderRadius: "0.375rem",
  +					border: "2px solid var(--border)",
  +					background: "var(--background)",
  +					boxShadow: "var(--shadow-card)",
  +					padding: "0.25rem",
  +				})}
  +			>
  +				<button
  +					type="button"
  +					onClick={() => onChange([])}
  +					className={css({ display: "flex", width: "100%", alignItems: "center", gap: "0.5rem", borderRadius: "0.25rem", paddingInline: "0.5rem", paddingBlock: "0.375rem", textAlign: "left", fontSize: "0.75rem", color: "var(--foreground)", _hover: { background: "var(--accent)" } })}
  +				>
  +					<span className={css({ display: "inline-flex", width: "1rem", justifyContent: "center" })}>{selected.length === 0 && <Check size={13} />}</span>
  +					{allLabel}
  +				</button>
  +				{options.map((option) => (
  +					<label key={option.value} className={css({ display: "flex", cursor: "pointer", alignItems: "center", gap: "0.5rem", borderRadius: "0.25rem", paddingInline: "0.5rem", paddingBlock: "0.375rem", fontSize: "0.75rem", color: "var(--foreground)", _hover: { background: "var(--accent)" } })}>
  +						<input
  +							type="checkbox"
  +							checked={selectedSet.has(option.value)}
  +							onChange={() => toggle(option.value)}
  +							className={css({ flexShrink: 0 })}
  +						/>
  +						<span className={css({ overflowWrap: "anywhere" })}>{option.label}</span>
  +					</label>
  +				))}
  +			</div>
  +		</details>
  +	);
  +}

  diff --git a/web/src/keating/coming-up.ts b/web/src/keating/coming-up.ts
  new file mode 100644
  index 0000000..ba914d7
  --- /dev/null
  +++ b/web/src/keating/coming-up.ts
  @@ -0,0 +1,160 @@
  +import type {
  +	FlashcardDeck,
  +	LearnerState,
  +	StudyPriority,
  +	StudyPriorityRecord,
  +	StudyPriorityTarget,
  +	Verification,
  +} from "./storage";
  +
  +const MS_PER_DAY = 86_400_000;
  +
  +export interface ComingUpItem {
  +	id: string;
  +	targetId: string;
  +	targetType: StudyPriorityTarget;
  +	priority: StudyPriority;
  +	prioritySource: "learner" | "recommended";
  +	title: string;
  +	topic: string;
  +	description: string;
  +	dueCount: number;
  +	overdueCount: number;
  +	nextDueAt: number | null;
  +	estimatedMinutes: number;
  +	weakConcepts: string[];
  +	cardCount: number;
  +	createdAt: number;
  +}
  +
  +export interface ComingUpQueue {
  +	items: ComingUpItem[];
  +	lanes: Record<StudyPriority, ComingUpItem[]>;
  +	dueCardCount: number;
  +	overdueCardCount: number;
  +	estimatedMinutes: number;
  +	dueDeckIds: string[];
  +}
  +
  +export interface ComingUpSources {
  +	decks: FlashcardDeck[];
  +	verifications: Verification[];
  +	learnerState: LearnerState;
  +	now?: number;
  +}
  +
  +function priorityFor(
  +	targetType: StudyPriorityTarget,
  +	targetId: string,
  +	recommended: StudyPriority,
  +	priorities: Map<string, StudyPriorityRecord>,
  +): Pick<ComingUpItem, "priority" | "prioritySource"> {
  +	const saved = priorities.get(`${targetType}:${targetId}`);
  +	return saved
  +		? { priority: saved.priority, prioritySource: "learner" }
  +		: { priority: recommended, prioritySource: "recommended" };
  +}
  +
  +function compareUrgency(left: ComingUpItem, right: ComingUpItem): number {
  +	if (left.overdueCount !== right.overdueCount) return right.overdueCount - left.overdueCount;
  +	if (left.dueCount !== right.dueCount) return right.dueCount - left.dueCount;
  +	const leftDue = left.nextDueAt ?? Number.POSITIVE_INFINITY;
  +	const rightDue = right.nextDueAt ?? Number.POSITIVE_INFINITY;
  +	if (leftDue !== rightDue) return leftDue - rightDue;
  +	return left.title.localeCompare(right.title);
  +}
  +
  +export function buildComingUpQueue({ decks, verifications, learnerState, now = Date.now() }: ComingUpSources): ComingUpQueue {
  +	const priorities = new Map(learnerState.studyPriorities.map((record) => [
  +		`${record.targetType}:${record.targetId}`,
  +		record,
  +	]));
  +	const topicProfiles = new Map(learnerState.topicProfiles.map((profile) => [profile.topic, profile]));
  +	const items: ComingUpItem[] = [];
  +
  +	for (const deck of decks) {
  +		const dueCards = deck.cards.filter((card) => card.srs.dueAt <= now);
  +		const overdueCards = dueCards.filter((card) => card.srs.dueAt < now - MS_PER_DAY);
  +		const nextDueAt = deck.cards.length > 0
  +			? Math.min(...deck.cards.map((card) => card.srs.dueAt))
  +			: null;
  +		const profile = topicProfiles.get(deck.topic);
  +		items.push({
  +			id: `deck:${deck.id}`,
  +			targetId: deck.id,
  +			targetType: "deck",
  +			...priorityFor("deck", deck.id, dueCards.length > 0 ? "focus" : "maintain", priorities),
  +			title: deck.title,
  +			topic: deck.topic,
  +			description: deck.description?.trim() || "Spaced-repetition deck",
  +			dueCount: dueCards.length,
  +			overdueCount: overdueCards.length,
  +			nextDueAt,
  +			estimatedMinutes: Math.max(1, Math.ceil(dueCards.length * 1.25)),
  +			weakConcepts: profile?.reportedChallenges ?? [],
  +			cardCount: deck.cards.length,
  +			createdAt: deck.createdAt,
  +		});
  +	}
  +
  +	for (const verification of verifications.filter((item) => !item.completed)) {
  +		const ageDays = Math.max(0, (now - verification.createdAt) / MS_PER_DAY);
  +		items.push({
  +			id: `verification:${verification.id}`,
  +			targetId: verification.id,
  +			targetType: "verification",
  +			...priorityFor("verification", verification.id, ageDays >= 7 ? "focus" : "maintain", priorities),
  +			title: `${verification.topic} check`,
  +			topic: verification.topic,
  +			description: verification.checklist.trim().split("\n").find(Boolean)?.replace(/^[-*\d.)\s]+/, "") || "Open knowledge check",
  +			dueCount: 0,
  +			overdueCount: 0,
  +			nextDueAt: null,
  +			estimatedMinutes: 5,
  +			weakConcepts: topicProfiles.get(verification.topic)?.reportedChallenges ?? [],
  +			cardCount: 0,
  +			createdAt: verification.createdAt,
  +		});
  +	}
  +
  +	for (const profile of learnerState.topicProfiles.filter((item) => item.status === "needs-review")) {
  +		const hasTopicWork = items.some((item) => item.topic === profile.topic);
  +		if (hasTopicWork) continue;
  +		items.push({
  +			id: `topic:${profile.topic}`,
  +			targetId: profile.topic,
  +			targetType: "topic",
  +			...priorityFor("topic", profile.topic, "focus", priorities),
  +			title: profile.topic,
  +			topic: profile.topic,
  +			description: "Needs a fresh retrieval check",
  +			dueCount: 0,
  +			overdueCount: 0,
  +			nextDueAt: null,
  +			estimatedMinutes: 8,
  +			weakConcepts: profile.reportedChallenges,
  +			cardCount: 0,
  +			createdAt: profile.lastEvidenceAt,
  +		});
  +	}
  +
  +	const sorted = [...items].sort(compareUrgency);
  +	const lanes: ComingUpQueue["lanes"] = { focus: [], maintain: [], low: [] };
  +	for (const item of sorted) lanes[item.priority].push(item);
  +	const dueDeckIds = sorted
  +		.filter((item) => item.targetType === "deck" && item.dueCount > 0)
  +		.sort((left, right) => {
  +			const priorityRank: Record<StudyPriority, number> = { focus: 0, maintain: 1, low: 2 };
  +			return priorityRank[left.priority] - priorityRank[right.priority] || compareUrgency(left, right);
  +		})
  +		.map((item) => item.targetId);
  +
  +	return {
  +		items: sorted,
  +		lanes,
  +		dueCardCount: sorted.reduce((sum, item) => sum + item.dueCount, 0),
  +		overdueCardCount: sorted.reduce((sum, item) => sum + item.overdueCount, 0),
  +		estimatedMinutes: sorted.reduce((sum, item) => sum + (item.dueCount > 0 ? item.estimatedMinutes : 0), 0),
  +		dueDeckIds,
  +	};
  +}

  diff --git a/web/src/keating/model-capabilities.ts b/web/src/keating/model-capabilities.ts
  new file mode 100644
  index 0000000..acfe4e8
  --- /dev/null
  +++ b/web/src/keating/model-capabilities.ts
  @@ -0,0 +1,36 @@
  +import type { Api, Model } from "@earendil-works/pi-ai/compat";
  +
  +export const LONG_CONTEXT_THRESHOLD = 256_000;
  +
  +export const CHAT_CAPABILITY_FILTERS = [
  +	{ value: "thinking", label: "Thinking" },
  +	{ value: "vision", label: "Vision" },
  +	{ value: "long-context", label: "Long context" },
  +] as const;
  +
  +export type ChatCapabilityFilter = (typeof CHAT_CAPABILITY_FILTERS)[number]["value"];
  +
  +export function modelHasCapability(model: Model<Api>, capability: ChatCapabilityFilter): boolean {
  +	switch (capability) {
  +		case "thinking":
  +			return model.reasoning === true;
  +		case "vision":
  +			return model.input.includes("image");
  +		case "long-context":
  +			return model.contextWindow >= LONG_CONTEXT_THRESHOLD;
  +		default:
  +			return true;
  +	}
  +}
  +
  +export function modelHasCapabilities(model: Model<Api>, capabilities: readonly ChatCapabilityFilter[]): boolean {
  +	return capabilities.every((capability) => modelHasCapability(model, capability));
  +}
  +
  +export function modelCapabilityBadges(model: Model<Api>): string[] {
  +	return [
  +		model.input.includes("image") ? "Vision" : "",
  +		model.reasoning ? "Thinking" : "",
  +		model.contextWindow >= LONG_CONTEXT_THRESHOLD ? "Long context" : "",
  +	].filter(Boolean);
  +}

